python3 << 'PYEOF'
import json

# Check §7 observations:对照三份 jsonl 中的关键行为
runs = {}
for name in ['main-bilibili-timeout', 'minimal-bilibili-success', 'social-analyzer-bilibili-success']:
    with open(f'/root/.openclaw/workspace/skills/public-social-account-analyzer/docs/observations/agent-runs/{name}.jsonl') as f:
        runs[name] = [json.loads(l) for l in f]

# For each run, extract the final assistant message content
for name, entries in runs.items():
    print(f"\n{'='*60}")
    print(f"=== {name} ===")
    # Find final assistant message
    assistant_messages = []
    for e in entries:
        if e.get('type') == 'message' and e.get('message', {}).get('role') == 'assistant':
            content = e.get('message', {}).get('content', [])
            for c in content:
                if c.get('type') == 'text':
                    assistant_messages.append(c.get('text', ''))

    if assistant_messages:
        final_msg = assistant_messages[-1]
        # Check for key issues
        print(f"Final message length: {len(final_msg)} chars")

        # Check for profile-as-work-evidence confusion
        if '主页' in final_msg and '作品' in final_msg:
            print("⚠️  可能把展示主页当作品证据")

        # Check for "待生成" mentions
        if '待生成' in final_msg:
            print("⚠️  提到'待生成'")

        # Check for audience claims
        if '受众' in final_msg or '观众' in final_msg:
            idx = final_msg.find('受众') if '受众' in final_msg else final_msg.find('观众')
            print(f"👥 受众/观众提及: ...{final_msg[max(0,idx-30):idx+50]}...")

        # Check for final-response/delivery-summary mention
        if 'final-response' in final_msg or 'delivery-summary' in final_msg:
            print("📄 提及 final-response/delivery-summary")
        else:
            print("📄 未提及 final-response/delivery-summary (可能依赖临场概括)")

print("\n" + "="*60)
print("Observation summary done")
PYEOF

