import json

# Deep dive into the key §7 observations
# Let me check each agent run for the specific issues mentioned

runs = {}
for name in ['main-bilibili-timeout', 'minimal-bilibili-success', 'social-analyzer-bilibili-success']:
    with open(f'/root/.openclaw/workspace/skills/public-social-account-analyzer/docs/observations/agent-runs/{name}.jsonl') as f:
        runs[name] = [json.loads(l) for l in f]

# Check 1: "不再把展示主页误当作品证据"
# Search for any mention of profile as work evidence
for name, entries in runs.items():
    print(f"\n{'='*60}")
    print(f"=== {name} ===")

    for e in entries:
        if e.get('type') == 'message' and e.get('message', {}).get('role') == 'assistant':
            content = e.get('message', {}).get('content', [])
            for c in content:
                if c.get('type') == 'text':
                    text = c.get('text', '')
                    # Look for profile being used as work evidence
                    if any(kw in text for kw in ['展示主页', '主页作为作品', 'profile as work', '主页是作品', '主页展示', '个人主页']):
                        print(f"  🔍 Profile/evidence issue: {text[:200]}...")
                    # Look for treating no comments as pending
                    if any(kw in text for kw in ['待生成', 'pending generation', '待采集评论']):
                        print(f"  📝 Comments pending: {text[:200]}...")
                    # Look for topic fragmentation  
                    if 'topic' in text.lower() and ('一条' in text or 'one per' in text.lower()):
                        print(f"  🏷️ Topic issue: {text[:200]}...")

print("\n" + "="*60)
print("Done checking historical issues")
PYEOF

